package eval

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// ExamSchema identifies an exam manifest: a JSON list of case.json files that
// live in several bank directories, pinned by content hash. The manifest is
// generated by `rwkv-lab exam build` and is the one scorable unit of the exam;
// the case files themselves stay where their authoring tools expect them.
const ExamSchema = "rwkv-exam/v1"

// ExamManifest is the machine-readable side of an exam's summary table.
type ExamManifest struct {
	Schema      string `json:"schema"`
	Name        string `json:"name"`
	Description string `json:"description"`
	// ToolCatalog and Harness are the run configuration the exam is scored
	// under; agent-eval refuses a conflicting --tool-catalog.
	ToolCatalog string `json:"tool_catalog"`
	Harness     string `json:"harness"`
	// Hash covers every case's id and case.json digest in manifest order, so
	// two runs are comparable exactly when their exam hashes match.
	Hash    string          `json:"hash"`
	Summary json.RawMessage `json:"summary,omitempty"`
	Cases   []ExamCase      `json:"cases"`
}

// ExamCase is one manifest row. Path is the repository-relative directory
// holding case.json; the descriptive fields are derived by the exam builder
// and are informational for the runner, which only checks id and digest.
type ExamCase struct {
	ID           string   `json:"id"`
	Suite        string   `json:"suite"`
	Path         string   `json:"path"`
	SHA256       string   `json:"sha256"`
	Scenario     string   `json:"scenario,omitempty"`
	TaskType     string   `json:"task_type,omitempty"`
	Level        string   `json:"level,omitempty"`
	Language     string   `json:"language"`
	UserTurns    int      `json:"user_turns"`
	RefCalls     *int     `json:"ref_calls,omitempty"`
	AnswerForm   string   `json:"answer_form"`
	Task         string   `json:"task"`
	Difficulties []string `json:"difficulties"`
	Author       string   `json:"author,omitempty"`
	Status       string   `json:"status,omitempty"`
	// Leaked marks a case whose content reached a training set; source-suite
	// listings keep it for history, exams leave it out.
	Leaked bool `json:"leaked,omitempty"`
}

// ExamHash is the comparability key of an ordered case list.
func ExamHash(cases []ExamCase) string {
	digest := sha256.New()
	for _, item := range cases {
		fmt.Fprintf(digest, "%s\t%s\n", item.ID, item.SHA256)
	}
	return hex.EncodeToString(digest.Sum(nil))
}

// FileSHA256 is the digest recorded for a case.json.
func FileSHA256(path string) (string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:]), nil
}

// IsExamManifest reports whether the JSON file at path declares ExamSchema.
func IsExamManifest(path string) bool {
	handle, err := os.Open(path)
	if err != nil {
		return false
	}
	defer handle.Close()
	head, _ := io.ReadAll(io.LimitReader(handle, 256))
	return bytes.Contains(head, []byte(`"schema"`)) && bytes.Contains(head, []byte(ExamSchema))
}

// ReadExamManifest decodes a manifest without loading its cases.
func ReadExamManifest(path string) (ExamManifest, error) {
	var manifest ExamManifest
	data, err := os.ReadFile(path)
	if err != nil {
		return manifest, err
	}
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&manifest); err != nil {
		return manifest, fmt.Errorf("decode exam manifest %s: %w", path, err)
	}
	if manifest.Schema != ExamSchema {
		return manifest, fmt.Errorf("%s: schema %q, want %q", path, manifest.Schema, ExamSchema)
	}
	if got := ExamHash(manifest.Cases); got != manifest.Hash {
		return manifest, fmt.Errorf("%s: hash %s does not match its cases (%s); rebuild with rwkv-lab exam build",
			path, manifest.Hash, got)
	}
	return manifest, nil
}

// LoadCasesManifest loads every case a manifest lists, in manifest order.
// repoRoot resolves the repository-relative case paths. A case.json whose
// digest differs from the manifest is an error: the exam changed without a
// rebuild, and a run against it would carry the wrong exam hash. Draft status
// does not gate manifest cases; membership is the manifest's decision.
func LoadCasesManifest(path string, repoRoot string) (ExamManifest, []Case, error) {
	manifest, err := ReadExamManifest(path)
	if err != nil {
		return manifest, nil, err
	}
	if repoRoot == "" {
		if repoRoot, err = moduleRoot(path); err != nil {
			return manifest, nil, err
		}
	}
	cases := make([]Case, 0, len(manifest.Cases))
	seen := make(map[string]bool, len(manifest.Cases))
	for _, item := range manifest.Cases {
		if seen[item.ID] {
			return manifest, nil, fmt.Errorf("%s: duplicate case id %q", path, item.ID)
		}
		seen[item.ID] = true
		file := filepath.Join(repoRoot, filepath.FromSlash(item.Path), "case.json")
		sum, err := FileSHA256(file)
		if err != nil {
			return manifest, nil, err
		}
		if sum != item.SHA256 {
			return manifest, nil, fmt.Errorf("%s: %s changed since the manifest was built (sha256 %s, manifest %s); rebuild with rwkv-lab exam build",
				path, file, sum[:12], item.SHA256[:min(12, len(item.SHA256))])
		}
		testCase, err := LoadCaseFile(file)
		if err != nil {
			return manifest, nil, err
		}
		if testCase.ID != item.ID {
			return manifest, nil, fmt.Errorf("%s: manifest id %q but file has %q", file, item.ID, testCase.ID)
		}
		cases = append(cases, testCase)
	}
	if len(cases) == 0 {
		return manifest, nil, fmt.Errorf("%s: no cases", path)
	}
	return manifest, cases, nil
}

// LoadCaseFile decodes and validates one bank-style case.json.
func LoadCaseFile(path string) (Case, error) {
	var testCase Case
	handle, err := os.Open(path)
	if err != nil {
		return testCase, err
	}
	defer handle.Close()
	data, err := io.ReadAll(io.LimitReader(handle, maxCaseFileBytes+1))
	if err != nil {
		return testCase, err
	}
	if len(data) > maxCaseFileBytes {
		return testCase, fmt.Errorf("%s: case file exceeds %d bytes", path, maxCaseFileBytes)
	}
	decoder := json.NewDecoder(strings.NewReader(string(data)))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&testCase); err != nil {
		return testCase, fmt.Errorf("decode %s: %w", path, err)
	}
	if decoder.Decode(&struct{}{}) != io.EOF {
		return testCase, fmt.Errorf("decode %s: trailing JSON value", path)
	}
	if err := ValidateCases([]Case{testCase}); err != nil {
		return testCase, fmt.Errorf("%s: %w", path, err)
	}
	return testCase, nil
}

// moduleRoot finds the repository root above a manifest: the nearest
// directory holding go.mod.
func moduleRoot(path string) (string, error) {
	dir, err := filepath.Abs(filepath.Dir(path))
	if err != nil {
		return "", err
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", fmt.Errorf("%s: no go.mod above the manifest to resolve case paths", path)
		}
		dir = parent
	}
}
